import shutilfrom pathlib import Pathdata_root = Path("data")output_root = Path("data/organized_spectra")output_root.mkdir(parents=True, exist_ok=True)def safe_name(x: str) -> str:    for ch in ['/', '\\', ':', '*', '?', '"', '<', '>', '|', ' ']:        x = x.replace(ch, '_')    return xdef extract_target(path: Path):    parts = path.parts    # ---------- KOA HIRES ----------    # data/koa/HIRES/KELT-1/lev1/extracted/.../file.fits    if "koa" in parts and "HIRES" in parts:        try:            i = parts.index("HIRES")            return parts[i+1]        except:            return None    # ---------- EXOFOP ----------    # data/exofop_spectra/TIC118327550/Spectrum_fits/file.fits    if "exofop_spectra" in parts:        try:            i = parts.index("exofop_spectra")            return parts[i+1]        except:            return None    return Nonefits_extensions = (".fits", ".fits.gz", ".fit")copied = 0checked = 0print("Scanning filesystem once...")for file_path in data_root.rglob("*"):    if not file_path.is_file():        continue    if not file_path.name.lower().endswith(fits_extensions):        continue    # don't copy from output folder    if output_root.resolve() in file_path.resolve().parents:        continue    checked += 1    target = extract_target(file_path)    if target is None:        continue    target_folder = output_root / safe_name(target)    target_folder.mkdir(parents=True, exist_ok=True)    dest = target_folder / file_path.name    try:        shutil.copy2(file_path, dest)        copied += 1        print(f"{target}  ->  {file_path.name}")    except Exception as e:        print("Error:", e)print()print("DONE")print("FITS files found:", checked)print("FITS files copied:", copied)print("Output location:", output_root.resolve())